const rotate = async (oldToken: string) => {
    const row = repo.findByHash(sha256(oldToken));
    if (!row || row.expires_at < Date.now() || repo.isFamilyRevoked(row.family_id)) {
      throw new InvalidToken();
    }
    if (row.revoked_at) {
      repo.revokeFamily(row.family_id);
      throw new TokenReuseDetected();
    }
    repo.revoke(row.id);
    ...
    repo.insert({ familyId: row.family_id, ... });
    return { access, refresh };
  };

const revokeFamily = (familyId: string): void => {
    db.prepare("UPDATE token_families SET revoked_at = ? WHERE id = ?").run(Date.now(), familyId);
    db.prepare("UPDATE refresh_tokens SET revoked_at = ? WHERE family_id = ? AND revoked_at IS NULL").run(Date.now(), familyId);
  };

const isFamilyRevoked = (familyId: string): boolean => {
    const row = db.prepare<[string], { revoked_at: number | null }>(
      "SELECT revoked_at FROM token_families WHERE id = ?"
    ).get(familyId);
    return row == null || row.revoked_at != null;
  };

const revoke = (id: number): void => {
    db.prepare("UPDATE refresh_tokens SET revoked_at = ? WHERE id = ?").run(Date.now(), id);
  };
